SELECT CAST(COUNT(DISTINCT CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN (a.dischtime - a.admittime) END) AS avg_los_readmitted, COUNT(DISTINCT CASE WHEN (a.dischtime - a.admittime) > INTERVAL '8 days' THEN a.subject_id END) * 100.0 / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS percentage_of_stays_over_8_days FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 77 AND 87 AND a.insurance = 'Medicare' AND a.admission_type = 'SNF' AND a.hadm_id IN (SELECT d.hadm_id FROM diagnoses_icd d WHERE d.icd_code = '426.0');